use serde_json::Value;
#[derive(Clone,Debug,PartialEq,Eq)]pub struct SearchSpec{pub biome_id:String,pub origin:[i32;3],pub radius:i32,pub horizontal_step:i32,pub vertical_step:i32}
pub fn parse_search(p:&Value,fallback:[i32;3])->Result<SearchSpec,String>{let o=p.as_object().ok_or_else(||"payload_must_be_object".to_owned())?;let raw=o.get("biome_id").or_else(||o.get("biome")).and_then(Value::as_str).ok_or_else(||"biome_id_required".to_owned())?;if !valid_id(raw)||raw.starts_with('#'){return Err("invalid_biome_id".into());}let id=if raw.contains(':'){raw.into()}else{format!("minecraft:{raw}")};let origin=match o.get("origin").and_then(Value::as_array){Some(v)if v.len()==3=>[coord(&v[0])?,coord(&v[1])?,coord(&v[2])?],Some(_)=>return Err("origin_must_have_three_coordinates".into()),None=>fallback};Ok(SearchSpec{biome_id:id,origin,radius:bounded(o.get("radius"),6400,1,6400)?,horizontal_step:bounded(o.get("horizontal_step"),32,1,64)?,vertical_step:bounded(o.get("vertical_step"),64,1,256)?})}
pub fn parse_samples(p:&Value,max:usize)->Result<Vec<[i32;3]>,String>{let a=p.get("positions").and_then(Value::as_array).ok_or_else(||"positions_array_required".to_owned())?;if a.is_empty(){return Err("at_least_one_sample_required".into());}if a.len()>max{return Err("too_many_biome_samples".into());}a.iter().map(|e|{let c=e.as_array().ok_or_else(||"sample_position_must_be_array".to_owned())?;if c.len()!=3{return Err("sample_position_must_have_three_coordinates".into());}Ok([coord(&c[0])?,coord(&c[1])?,coord(&c[2])?])}).collect()}
fn coord(v:&Value)->Result<i32,String>{let n=v.as_i64().ok_or_else(||"coordinate_must_be_integer".to_owned())?;if !(-30_000_000..=30_000_000).contains(&n){return Err("coordinate_out_of_world_bounds".into());}Ok(n as i32)}
fn bounded(v:Option<&Value>,d:i32,min:i32,max:i32)->Result<i32,String>{match v{None=>Ok(d),Some(v)=>{let n=v.as_i64().ok_or_else(||"search_parameter_must_be_integer".to_owned())?;if n<i64::from(min)||n>i64::from(max){return Err("search_parameter_out_of_bounds".into());}Ok(n as i32)}}}
fn valid_id(v:&str)->bool{if v.is_empty()||v.len()>256{return false;}let(ns,p)=v.split_once(':').unwrap_or(("minecraft",v));!ns.is_empty()&&!p.is_empty()&&ns.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||matches!(b,b'_'|b'-'|b'.'))&&p.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||matches!(b,b'_'|b'-'|b'.'|b'/'))}
#[cfg(test)]mod tests{use super::*;use serde_json::json;#[test]fn search_normalizes_and_bounds(){let s=parse_search(&json!({"biome_id":"forest"}),[10,64,-5]).unwrap();assert_eq!(s.biome_id,"minecraft:forest");assert_eq!(s.origin,[10,64,-5]);assert!(parse_search(&json!({"biome_id":"#minecraft:is_forest"}),[0,0,0]).is_err());assert!(parse_search(&json!({"biome_id":"forest","radius":90000}),[0,0,0]).is_err());}#[test]fn sample_batch_is_bounded(){assert_eq!(parse_samples(&json!({"positions":[[-1,64,-5]]}),4).unwrap(),vec![[-1,64,-5]]);assert!(parse_samples(&json!({"positions":[]}),4).is_err());assert!(parse_samples(&json!({"positions":[[0,0,0],[1,1,1]]}),1).is_err());}}
